KINDS = ["identity","classification","relationship","measurement","evidence","quality","authority","ownership","temporal","state","lifecycle","provenance","privacy","retention","access","validation","interoperability","decision","exception","security"]

def finding(item, number, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(number + 4) % len(KINDS)], KINDS[(number + 11) % len(KINDS)]]
    questions = [
      {"id":f"{fid}-q01","text":f"Which stable identities, profile, clinical meanings, values and explicit unknowns establish {low}?","kind":kinds[0],"answer_data":["identifiers and profile","coded and original meanings","values, qualifiers and unknowns"]},
      {"id":f"{fid}-q02","text":f"Who or what supplied, performed, recorded, interpreted or accepted responsibility for {low}, using which method, evidence and authority?","kind":kinds[1],"answer_data":["participants and roles","method and evidence","authority, confidence and limitations"]},
      {"id":f"{fid}-q03","text":f"Which event, effective, specimen, onset, issued, recorded and knowledge times apply to {low}, and how may it be validated, challenged, corrected or retained?","kind":kinds[2],"answer_data":["distinct clinical and record times","validation and challenge","successor correction and retention"]},
    ]
    return {"id":fid,"name":name,"description":f"Records {low} as a source-qualified clinical assertion while preserving external clinical masters and the separation between observable, result, interpretation and diagnosis.","source_refs":refs,"questions":questions,"data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Typed clinical assertion data for {low}, including profile, source meaning, context, time, authority, status and provenance.","value_kind":"collection","cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],"artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Immutable or successor-versioned evidence-bearing record for {low}.","media_or_form":["logical clinical assertion","observation, assessment, status, provenance or projection record"],"serial":True,"identity_strategy":f"Clinical assertion ID plus {fid} statement or event ID; patient name, code, value, encounter and date never identify the assertion alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    bundles=[]; number=0
    for bid,bname,rationale,layers in ROWS:
        rendered=[]
        for lid,lname,refs,items in layers:
            values=[]
            for item in items:
                number += 1
                values.append(finding(item,number,refs))
            rendered.append({"id":lid,"name":lname,"description":f"Groups source-qualified clinical context for {lname.lower()}.","source_refs":refs,"findings":values})
        bundles.append({"id":bid,"name":bname,"description":f"Groups governed clinical assertion context for {bname.lower()}.","rationale":rationale+".","source_refs":sorted({ref for layer in layers for ref in layer[2]}),"layers":rendered})
    return {"bundles":bundles}

